mapper.select:
select id, order_no, applicant_id, applicant_name, applicant_employee_no, applicant_department_id, applicant_department_name, reason, estimated_residual_value, approval_status, approval_remark, approver_name, approved_at, created_at, updated_at from scrap_order
and order_no like concat('%',#{orderNo},'%')
and applicant_name like concat('%',#{applicantName},'%')
and applicant_employee_no like concat('%',#{applicantEmployeeNo},'%')
and applicant_department_name like concat('%',#{applicantDepartmentName},'%')
and approver_name like concat('%',#{approvalName},'%')
and approval_status = #{approvalStatus}
and created_at >= #{startDate}
and created_at <= #{endDate}
